package org.apache.commons.lang.builder;

import junit.framework.TestCase;
import java.math.BigDecimal;

public class AgentBRT_Lang_48_raw_diff_Test extends TestCase {

    public void testReproduceBug() {
        EqualsBuilder equalsBuilder = new EqualsBuilder();
        BigDecimal lhs = new BigDecimal("1.0");
        BigDecimal rhs = new BigDecimal("1.00");
        equalsBuilder.append(lhs, rhs);
        assertFalse("BigDecimal comparison should fail due to scale difference", equalsBuilder.isEquals());
    }
}

